package com.example.billing.domain;
import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="Subscriptions",indexes=@Index(name="IX_Subscriptions_CustomerId",columnList="CustomerId")) public class Subscription { @Id @Column(name="Id") public UUID id; @Column(name="CustomerId",nullable=false) public UUID customerId; @Column(name="PricePlanId",nullable=false) public UUID pricePlanId; @Column(name="Status",length=50,nullable=false) public String status; @Column(name="StartDate",nullable=false) public LocalDate startDate; @Column(name="CurrentPeriodStart",nullable=false) public LocalDate currentPeriodStart; @Column(name="CurrentPeriodEnd",nullable=false) public LocalDate currentPeriodEnd; @Column(name="CancelAtPeriodEnd",nullable=false) public boolean cancelAtPeriodEnd; }
